package com.vandorlabs.neoforge.reservoir;
import java.util.*;import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.core.registries.BuiltInRegistries;import net.minecraft.world.level.block.state.BlockState;import net.neoforged.neoforge.fluids.FluidStack;import net.neoforged.neoforge.fluids.capability.IFluidHandler;
/** Each tank owns exactly its local 16 buckets; aggregation never redistributes or copies storage. */
public final class NativeHexTankEntity extends NativeBufferEntity implements IFluidHandler {
 public static final int CAPACITY=16000;private FluidStack fluid=FluidStack.EMPTY;
 public NativeHexTankEntity(BlockPos pos,BlockState state){super(NativeBufferBindings.TANK_ENTITY,pos,state,false);}
 public IFluidHandler fluid(Direction side){return side==null||side.getAxis()==facing().getAxis()?this:null;}
 public FluidStack localFluid(){return inert()?FluidStack.EMPTY:fluid.copy();}
 /** Client drawing uses the immutable-for-that-update visual stack; server callers receive a copy. */
 public FluidStack visibleFluid(){return inert()?FluidStack.EMPTY:getLevel()==null||getLevel().isClientSide?fluid:fluid.copy();}
 FluidStack storedFluid(){return fluid;}public int amount(){return inert()?0:fluid.getAmount();}public int capacity(){return CAPACITY;}
 public List<NativeHexTankEntity> members(){return NativeTankGroups.members(this);}
 public int getTanks(){return members().size();}private NativeHexTankEntity member(int n){var cells=members();if(n<0||n>=cells.size())throw new IndexOutOfBoundsException();return cells.get(n);}
 public FluidStack getFluidInTank(int n){return member(n).localFluid();}public int getTankCapacity(int n){member(n);return CAPACITY;}public boolean isFluidValid(int n,FluidStack value){member(n);return !value.isEmpty();}
 public int fill(FluidStack offer,FluidAction action){if(!installed()||offer.isEmpty())return 0;var cells=members();for(var cell:cells)if(!cell.fluid.isEmpty()&&!FluidStack.isSameFluidSameComponents(cell.fluid,offer))return 0;int remaining=offer.getAmount();for(var cell:cells){int n=Math.min(remaining,CAPACITY-cell.fluid.getAmount());if(n>0&&action.execute()){boolean identityChanged=cell.fluid.isEmpty();if(cell.fluid.isEmpty())cell.fluid=offer.copyWithAmount(n);else cell.fluid.grow(n);cell.contentsChanged(identityChanged);}remaining-=n;if(remaining==0)break;}return offer.getAmount()-remaining;}
 public FluidStack drain(FluidStack request,FluidAction action){if(!installed()||request.isEmpty())return FluidStack.EMPTY;int remaining=request.getAmount(),taken=0;for(var cell:members()){if(cell.fluid.isEmpty()||!FluidStack.isSameFluidSameComponents(cell.fluid,request))continue;int n=Math.min(remaining,cell.fluid.getAmount());if(action.execute()&&n>0){boolean identityChanged=n==cell.fluid.getAmount();cell.fluid.shrink(n);if(cell.fluid.isEmpty())cell.fluid=FluidStack.EMPTY;cell.contentsChanged(identityChanged);}remaining-=n;taken+=n;if(remaining==0)break;}return taken==0?FluidStack.EMPTY:request.copyWithAmount(taken);}
 public FluidStack drain(int maximum,FluidAction action){if(maximum<=0||!installed())return FluidStack.EMPTY;for(var cell:members())if(!cell.fluid.isEmpty())return drain(cell.fluid.copyWithAmount(maximum),action);return FluidStack.EMPTY;}
 protected void readContents(CompoundTag tag,HolderLookup.Provider registries){fluid=FluidStack.EMPTY;if(tag.contains("Tank")&&!tag.contains("Tank",Tag.TAG_COMPOUND))throw new IllegalArgumentException("Malformed legacy tank");if(tag.contains("NativeTankFluid")){fluid=FluidStack.parse(registries,tag.get("NativeTankFluid")).orElseThrow(()->new IllegalArgumentException("Unknown tank fluid"));if(fluid.isEmpty()||!fluid.save(registries).equals(tag.get("NativeTankFluid")))throw new IllegalArgumentException("Unknown tank fluid fields");}else if(tag.contains("Tank",Tag.TAG_COMPOUND)){var old=tag.getCompound("Tank");if(old.contains("FluidName")&&!old.contains("FluidName",Tag.TAG_STRING)||old.contains("Amount")&&!old.contains("Amount",Tag.TAG_INT)||old.contains("Tag")&&!old.contains("Tag",Tag.TAG_COMPOUND))throw new IllegalArgumentException("Malformed legacy fluid fields");for(String key:old.getAllKeys())if(!Set.of("FluidName","Amount","Tag","Empty").contains(key))throw new IllegalArgumentException("Unknown legacy tank field");if(old.contains("FluidName")){if(old.getInt("Amount")<=0)throw new IllegalArgumentException("Invalid legacy tank amount");var id=ResourceLocation.tryParse(old.getString("FluidName"));if(id==null||!BuiltInRegistries.FLUID.containsKey(id)||old.contains("Tag")&&!old.getCompound("Tag").isEmpty())throw new IllegalArgumentException("Unsupported legacy tank fluid");var value=BuiltInRegistries.FLUID.get(id);if(value==net.minecraft.world.level.material.Fluids.EMPTY)throw new IllegalArgumentException("Unknown legacy tank fluid");fluid=new FluidStack(value,old.getInt("Amount"));}}
 if(fluid.getAmount()<0||fluid.getAmount()>CAPACITY)throw new IllegalArgumentException("Oversized tank fluid");}
 protected void writeContents(CompoundTag tag,HolderLookup.Provider registries){tag.remove("Tank");tag.remove("NativeTankFluid");if(!fluid.isEmpty())tag.put("NativeTankFluid",fluid.save(registries));}
}
